const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");

// Icon helpers
const { FaExclamationTriangle, FaMemory, FaMobileAlt, FaMicrochip, FaCompressArrowsAlt, FaExpandArrowsAlt, FaChartBar, FaRocket, FaLightbulb, FaBolt, FaCheckCircle, FaCogs, FaDatabase, FaEye, FaArrowRight, FaLayerGroup } = require("react-icons/fa");

function renderIconSvg(IconComponent, color = "#000000", size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

// Color palette - deep tech / ML feel
const C = {
  navy: "0F1B2D",
  darkBlue: "162A45",
  midBlue: "1B3A5C",
  accent: "00B4D8",    // cyan accent
  accentDark: "0090B0",
  highlight: "48CAE4",
  orange: "FF8C42",
  green: "06D6A0",
  white: "FFFFFF",
  offWhite: "F0F4F8",
  lightGray: "E2E8F0",
  medGray: "94A3B8",
  darkText: "1E293B",
  bodyText: "334155",
  subtleText: "64748B",
};

const FONT_TITLE = "Arial Black";
const FONT_BODY = "Calibri";

const mkShadow = () => ({ type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.12 });

async function main() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "SmolVLM Research Team";
  pres.title = "SmolVLM: Redefining Small and Efficient Multimodal Models";

  // Pre-render icons
  const icons = {};
  const iconList = [
    ["warning", FaExclamationTriangle, "#" + C.orange],
    ["memory", FaMemory, "#" + C.accent],
    ["mobile", FaMobileAlt, "#" + C.green],
    ["chip", FaMicrochip, "#" + C.accent],
    ["compress", FaCompressArrowsAlt, "#" + C.accent],
    ["expand", FaExpandArrowsAlt, "#" + C.orange],
    ["chart", FaChartBar, "#" + C.accent],
    ["rocket", FaRocket, "#" + C.green],
    ["bulb", FaLightbulb, "#" + C.orange],
    ["bolt", FaBolt, "#" + C.accent],
    ["check", FaCheckCircle, "#" + C.green],
    ["cogs", FaCogs, "#" + C.highlight],
    ["eye", FaEye, "#" + C.accent],
    ["arrow", FaArrowRight, "#" + C.white],
    ["layer", FaLayerGroup, "#" + C.accent],
    ["checkWhite", FaCheckCircle, "#" + C.white],
    ["boltWhite", FaBolt, "#" + C.white],
    ["compressWhite", FaCompressArrowsAlt, "#" + C.white],
    ["expandWhite", FaExpandArrowsAlt, "#" + C.white],
    ["chipWhite", FaMicrochip, "#" + C.white],
    ["bulbWhite", FaLightbulb, "#" + C.white],
  ];
  for (const [name, comp, color] of iconList) {
    icons[name] = await iconToBase64Png(comp, color);
  }

  // ─── SLIDE 1: Title ───
  {
    const slide = pres.addSlide();
    slide.background = { color: C.navy };
    // Decorative accent bar top
    slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.accent } });
    // Subtle side accent
    slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0.8, w: 0.08, h: 2.5, fill: { color: C.accent } });

    slide.addText("SmolVLM", {
      x: 0.7, y: 1.0, w: 9, h: 1.2,
      fontSize: 48, fontFace: FONT_TITLE, color: C.white, bold: true, margin: 0
    });
    slide.addText("Redefining Small and Efficient Multimodal Models", {
      x: 0.7, y: 2.1, w: 8, h: 0.7,
      fontSize: 22, fontFace: FONT_BODY, color: C.highlight, margin: 0
    });
    slide.addText("Hugging Face & Stanford University", {
      x: 0.7, y: 3.0, w: 6, h: 0.4,
      fontSize: 14, fontFace: FONT_BODY, color: C.medGray, margin: 0
    });
    // Key stat callouts
    const stats = [
      { val: "256M", label: "Smallest Model" },
      { val: "<1GB", label: "GPU RAM" },
      { val: "300×", label: "vs Idefics-80B" },
    ];
    stats.forEach((s, i) => {
      const sx = 0.7 + i * 2.8;
      slide.addShape(pres.shapes.RECTANGLE, { x: sx, y: 3.8, w: 2.4, h: 1.1, fill: { color: C.darkBlue }, shadow: mkShadow() });
      slide.addText(s.val, { x: sx, y: 3.85, w: 2.4, h: 0.65, fontSize: 28, fontFace: FONT_TITLE, color: C.accent, align: "center", valign: "middle", margin: 0, bold: true });
      slide.addText(s.label, { x: sx, y: 4.45, w: 2.4, h: 0.4, fontSize: 11, fontFace: FONT_BODY, color: C.medGray, align: "center", valign: "top", margin: 0 });
    });
  }

  // ─── SLIDE 2: Problem / Motivation ───
  {
    const slide = pres.addSlide();
    slide.background = { color: C.offWhite };
    slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.accent } });

    slide.addText("Large VLMs Are Powerful but Impractical for Edge Deployment", {
      x: 0.6, y: 0.3, w: 8.8, h: 0.7,
      fontSize: 26, fontFace: FONT_TITLE, color: C.darkText, margin: 0
    });

    // Left column: problem bullets with icons
    const problems = [
      { icon: "warning", title: "Massive Memory Footprint", desc: "Molmo-A1B-7B requires 27.7 GB GPU RAM — impossible on mobile devices" },
      { icon: "chip", title: "Compute-Heavy Inference", desc: "State-of-the-art VLMs need high-end GPUs, blocking edge deployment" },
      { icon: "expand", title: "Long Token Sequences", desc: "High-res images generate thousands of visual tokens, overwhelming small LMs" },
    ];
    problems.forEach((p, i) => {
      const py = 1.3 + i * 1.2;
      slide.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: py, w: 5.2, h: 1.0, fill: { color: C.white }, shadow: mkShadow() });
      slide.addImage({ data: icons[p.icon], x: 0.8, y: py + 0.2, w: 0.45, h: 0.45 });
      slide.addText(p.title, { x: 1.45, y: py + 0.08, w: 4.1, h: 0.4, fontSize: 14, fontFace: FONT_BODY, color: C.darkText, bold: true, margin: 0 });
      slide.addText(p.desc, { x: 1.45, y: py + 0.48, w: 4.1, h: 0.45, fontSize: 11, fontFace: FONT_BODY, color: C.subtleText, margin: 0 });
    });

    // Right column: RAM comparison
    slide.addText("GPU RAM Comparison", {
      x: 6.2, y: 1.3, w: 3.5, h: 0.4,
      fontSize: 14, fontFace: FONT_BODY, color: C.darkText, bold: true, margin: 0
    });
    const ramData = [
      { name: "SmolVLM-256M", ram: 0.8, color: C.green },
      { name: "SmolVLM-500M", ram: 1.2, color: C.accent },
      { name: "SmolVLM-2.2B", ram: 4.9, color: C.highlight },
      { name: "Molmo-A1B-7B", ram: 27.7, color: C.orange },
    ];
    const maxRam = 27.7;
    const barMaxW = 2.8;
    ramData.forEach((d, i) => {
      const by = 1.9 + i * 0.75;
      slide.addText(d.name, { x: 6.2, y: by, w: 3.2, h: 0.25, fontSize: 10, fontFace: FONT_BODY, color: C.bodyText, margin: 0 });
      const bw = Math.max((d.ram / maxRam) * barMaxW, 0.15);
      slide.addShape(pres.shapes.RECTANGLE, { x: 6.2, y: by + 0.28, w: bw, h: 0.22, fill: { color: d.color } });
      slide.addText(d.ram + " GB", { x: 6.2 + bw + 0.1, y: by + 0.25, w: 0.8, h: 0.28, fontSize: 10, fontFace: FONT_BODY, color: C.bodyText, bold: true, margin: 0 });
    });
  }

  // ─── SLIDE 3: Architecture Overview ───
  {
    const slide = pres.addSlide();
    slide.background = { color: C.offWhite };
    slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.accent } });

    slide.addText("SmolVLM Architecture Pipeline", {
      x: 0.6, y: 0.3, w: 8.8, h: 0.7,
      fontSize: 26, fontFace: FONT_TITLE, color: C.darkText, margin: 0
    });

    // Pipeline steps as connected cards
    const steps = [
      { num: "1", title: "Image\nSplitting", desc: "Split into sub-images for high-res processing", color: C.accent },
      { num: "2", title: "SigLIP\nEncoder", desc: "93M param vision encoder extracts features", color: C.accentDark },
      { num: "3", title: "Pixel\nShuffle", desc: "r=4 compression: 16× token reduction", color: C.green },
      { num: "4", title: "Linear\nProjection", desc: "Map visual features to LM input space", color: C.highlight },
      { num: "5", title: "SmolLM2\nBackbone", desc: "Compact LM generates text output", color: C.orange },
    ];
    const cardW = 1.55;
    const gap = 0.25;
    const totalW = steps.length * cardW + (steps.length - 1) * gap;
    const startX = (10 - totalW) / 2;

    steps.forEach((s, i) => {
      const cx = startX + i * (cardW + gap);
      // Card
      slide.addShape(pres.shapes.RECTANGLE, { x: cx, y: 1.3, w: cardW, h: 2.8, fill: { color: C.white }, shadow: mkShadow() });
      // Colored top bar
      slide.addShape(pres.shapes.RECTANGLE, { x: cx, y: 1.3, w: cardW, h: 0.08, fill: { color: s.color } });
      // Step number circle
      slide.addShape(pres.shapes.OVAL, { x: cx + (cardW - 0.55) / 2, y: 1.55, w: 0.55, h: 0.55, fill: { color: s.color } });
      slide.addText(s.num, { x: cx + (cardW - 0.55) / 2, y: 1.55, w: 0.55, h: 0.55, fontSize: 20, fontFace: FONT_TITLE, color: C.white, align: "center", valign: "middle", margin: 0 });
      // Title
      slide.addText(s.title, { x: cx + 0.1, y: 2.25, w: cardW - 0.2, h: 0.7, fontSize: 13, fontFace: FONT_BODY, color: C.darkText, bold: true, align: "center", valign: "middle", margin: 0 });
      // Description
      slide.addText(s.desc, { x: cx + 0.1, y: 3.0, w: cardW - 0.2, h: 0.9, fontSize: 10, fontFace: FONT_BODY, color: C.subtleText, align: "center", valign: "top", margin: 0 });
      // Arrow between cards
      if (i < steps.length - 1) {
        slide.addShape(pres.shapes.LINE, {
          x: cx + cardW + 0.02, y: 2.7, w: gap - 0.04, h: 0,
          line: { color: C.medGray, width: 2 }
        });
      }
    });

    // Bottom note
    slide.addText("Video: frames sampled and processed through the same pipeline", {
      x: 0.6, y: 4.5, w: 8.8, h: 0.4,
      fontSize: 11, fontFace: FONT_BODY, color: C.subtleText, italic: true, margin: 0
    });
  }

  // ─── SLIDE 4: Compute Allocation (Finding 1) ───
  {
    const slide = pres.addSlide();
    slide.background = { color: C.offWhite };
    slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.accent } });

    slide.addText("Smaller Vision Encoders Outperform Larger Ones in Compact VLMs", {
